export const circuit=[{id:'body',name:'Body tissues',oxygen:'Oxygen leaves blood'},{id:'vena',name:'Vena cava',oxygen:'Lower oxygen'},{id:'ra',name:'Right atrium',oxygen:'Lower oxygen'},{id:'rv',name:'Right ventricle',oxygen:'Lower oxygen'},{id:'pa',name:'Pulmonary artery',oxygen:'Lower oxygen'},{id:'lungs',name:'Lung capillaries',oxygen:'Oxygen enters blood'},{id:'pv',name:'Pulmonary vein',oxygen:'Higher oxygen'},{id:'la',name:'Left atrium',oxygen:'Higher oxygen'},{id:'lv',name:'Left ventricle',oxygen:'Higher oxygen'},{id:'aorta',name:'Aorta',oxygen:'Higher oxygen'},{id:'body',name:'Body tissues',oxygen:'Oxygen leaves blood'}];
export const vesselCases=[{id:'artery',name:'Artery',wall:'thick',lumen:'small',valve:'no',reason:'pressure'},{id:'vein',name:'Vein',wall:'thin',lumen:'large',valve:'yes',reason:'return'},{id:'capillary',name:'Capillary',wall:'one',lumen:'small',valve:'no',reason:'exchange'}];
export function vesselValid(id,w){const v=vesselCases.find(v=>v.id===id);return !!v&&['wall','lumen','valve','reason'].every(k=>w[k]===v[k]);}
export function valveFlow(valve,direction){return direction==='forward'?'Forward flow allowed':valve==='working'?'Backflow blocked':'Backflow through leaky valve';}
export function bloodFlow(volume,time){return time>0?volume/time:null;}
export const bloodParts=[{id:'red',name:'Red blood cell',feature:'Haemoglobin',result:'Oxygen can be carried by haemoglobin',missing:'Oxygen-carrying capacity reduced',reason:'oxygen'},{id:'white',name:'White blood cell',feature:'Defence function',result:'Pathogen defence represented',missing:'Defence impaired in this comparison',reason:'defence'},{id:'platelet',name:'Platelets',feature:'Platelet fragments',result:'Clot forms at the damaged site',missing:'Platelet plug fails to form',reason:'clot'},{id:'plasma',name:'Plasma',feature:'Liquid carrier',result:'Dissolved substances transported',missing:'Normal transport of dissolved substances disrupted',reason:'transport'}];
export function gasSnapshot(step){const s=Math.max(0,Math.min(2,Number(step)||0));return {oxygen:{air:6-s,blood:2+s},carbon:{air:2+s,blood:6-s}};}
export function exchangeCase({area='normal',wall='thin',air='on',blood='on'}={}){return {key:[area,wall,air,blood].join(':'),effects:[area==='reduced'?'Less exchange surface':null,wall==='thick'?'Longer diffusion distance':null,air==='off'?'Ventilation no longer refreshes alveolar air':null,blood==='off'?'Blood flow no longer maintains blood-side gradients':null].filter(Boolean)};}
export const exchangeComparisons=['normal:thin:on:on','reduced:thin:on:on','normal:thick:on:on','normal:thin:off:on','normal:thin:on:off'];
